      "id": "36350632",
      "title": "芯片战争",
      "category": "科技",
      "作者": "克里斯·米勒",
      "国籍": "美",
      "译者": "蔡树军",
      "出版社": "浙江人民出版社",
      "出版年": "2023-5",
      "ISBN": "9787213109959",
